{"name":"firebase_init","description":"Use this to initialize selected Firebase services in the workspace (Cloud Firestore database, Firebase SQL Connect, Firebase Realtime Database, Firebase AI Logic). All services are optional; specify only the products you want to set up. You can initialize new features into an existing project directory, but re-initializing an existing feature may overwrite configuration. To deploy the initialized features, run the `firebase deploy` command after `firebase_init` tool.","parameters":{"properties":{"features":{"properties":{"ailogic":{"description":"Enable Firebase AI Logic feature for existing app","properties":{"app_id":{"description":"Firebase app ID (format: 1:PROJECT_NUMBER:PLATFORM:APP_ID). Must be an existing app in your Firebase project.","type":"string"}},"required":["app_id"],"type":"object"},"auth":{"description":"Provide this object to initialize Firebase Authentication.","properties":{"providers":{"properties":{"anonymous":{"description":"Enable Anonymous authentication.","type":"boolean"},"emailPassword":{"description":"Enable Email/Password authentication.","type":"boolean"},"googleSignIn":{"description":"Configure Google Sign-In.","properties":{"oAuthBrandDisplayName":{"description":"The display name for the OAuth brand.","type":"string"},"supportEmail":{"description":"The support email for the OAuth brand.","type":"string"}},"required":["oAuthBrandDisplayName","supportEmail"],"type":"object"}},"type":"object"}},"required":["providers"],"type":"object"},"database":{"description":"Provide this object to initialize Firebase Realtime Database in this project directory.","properties":{"rules":{"default":"{
  "rules": {
    ".read": "auth != null",
    ".write": "auth != null"
  }
}","description":"The security rules to use for Realtime Database Security Rules.","type":"string"},"rules_filename":{"default":"database.rules.json","description":"The file to use for Realtime Database Security Rules.","type":"string"}},"type":"object"},"dataconnect":{"description":"Provide this object to initialize Firebase SQL Connect with Cloud SQL Postgres in this project directory.
It installs SQL Connect Generated SDKs in all detected apps in the folder.","properties":{"cloudsql_database":{"default":"fdcdb","description":"The Postgres database ID to use in the Firebase SQL Connect service.","type":"string"},"cloudsql_instance_id":{"description":"The GCP Cloud SQL instance ID to use in the Firebase SQL Connect service. By default, use <serviceId>-fdc. 
Set `provision_cloudsql` to true to start Cloud SQL provisioning.","type":"string"},"location_id":{"default":"us-east4","description":"The GCP region ID to set up the Firebase SQL Connect service.","type":"string"},"provision_cloudsql":{"default":false,"description":"If true, provision the Cloud SQL instance if `cloudsql_instance_id` does not exist already. 
The first Cloud SQL instance in the project will use the SQL Connect no-cost trial. See its terms of service: https://firebase.google.com/pricing.","type":"boolean"},"service_id":{"description":"The Firebase SQL Connect service ID to initialize. Default to match the current folder name.","type":"string"}},"type":"object"},"firestore":{"description":"Provide this object to initialize Cloud Firestore in this project directory.","properties":{"database_id":{"default":"(default)","description":"The database ID to use for Firestore.","type":"string"},"location_id":{"default":"nam5","description":"The GCP region ID to set up the Firestore database.","type":"string"},"rules":{"description":"The security rules to use for Firestore Security Rules. Default to open rules that expire in 30 days.","type":"string"},"rules_filename":{"default":"firestore.rules","description":"The file to use for Firestore Security Rules.","type":"string"}},"type":"object"},"hosting":{"description":"Provide this object to initialize Firebase Hosting in this project directory.","properties":{"public_directory":{"default":"public","description":"The directory containing public files that will be served. If using a build tool, this likely should be the output directory of that tool.","type":"string"},"single_page_app":{"default":false,"description":"Configure as a single-page app.","type":"boolean"},"site_id":{"description":"The ID of the hosting site to configure. If omitted and there is a default hosting site, that will be used.","type":"string"}},"type":"object"},"storage":{"description":"Provide this object to initialize Firebase Storage in this project directory.","properties":{"rules":{"description":"The security rules to use for Firebase Storage Security Rules. Default to closed rules that deny all access.","type":"string"},"rules_filename":{"default":"storage.rules","description":"The file to use for Firebase Storage Security Rules.","type":"string"}},"type":"object"}},"type":"object"}},"required":["features"],"type":"object"}}

{
  "artifactType": "ARTIFACT_TYPE_IMPLEMENTATION_PLAN",
  "summary": "This plan details the design of a Google Drive search tool that combines authenticated API searching (via service accounts or OAuth2 desktop flows) with OSINT Google Dorking generator to search public files. It will include a CLI python script (search_drive.py) and a premium, responsive Web UI (dashboard.html) for a local search dashboard.",
  "updatedAt": "2026-05-23T19:09:46.035872600Z",
  "requestFeedback": true
}

